/**
 * Python's whitespace notion, as used by `str.strip()` / `str.rstrip()` and by
 * the `int()` constructor.
 *
 * This is deliberately *not* JavaScript's `String.prototype.trim()` set: Python
 * treats the C0 separators U+001C..U+001F and U+0085 as whitespace (JS does
 * not), while JS treats U+FEFF (BOM) as whitespace (Python does not).
 * Verified against the reference build: `--c "z"` decodes to 57 (the
 * character is stripped) whereas `--c "z﻿"` raises.
 */

const SEPARATOR_CODE_POINTS = new Set([
  0x1c, 0x1d, 0x1e, 0x1f, // FILE / GROUP / RECORD / UNIT SEPARATOR
  0x85, // NEXT LINE
  0xa0, // NO-BREAK SPACE
  0x1680, // OGHAM SPACE MARK
  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
]);

/** True when Python's `chr(codePoint).isspace()` would be true. */
export function isPySpace(codePoint) {
  if (codePoint >= 0x09 && codePoint <= 0x0d) return true; // \t \n \v \f \r
  if (codePoint === 0x20) return true;
  if (codePoint >= 0x2000 && codePoint <= 0x200a) return true; // EN QUAD..HAIR SPACE
  return SEPARATOR_CODE_POINTS.has(codePoint);
}

function isSpaceChar(char) {
  return isPySpace(char.codePointAt(0));
}

/** Equivalent of Python's `text.rstrip()` (no argument). */
export function pyRstrip(text) {
  const chars = Array.from(text);
  let end = chars.length;
  while (end > 0 && isSpaceChar(chars[end - 1])) end -= 1;
  return chars.slice(0, end).join('');
}

/** Equivalent of Python's `text.lstrip()` (no argument). */
export function pyLstrip(text) {
  const chars = Array.from(text);
  let start = 0;
  while (start < chars.length && isSpaceChar(chars[start])) start += 1;
  return chars.slice(start).join('');
}

/** Equivalent of Python's `text.strip()` (no argument). */
export function pyStrip(text) {
  return pyLstrip(pyRstrip(text));
}

