/**
 * Decimal digit values for the whole Unicode `Nd` category, which is what
 * Python's `int()` accepts.  The reference build parses `--a ١٢٣`, `--a １２`
 * and `--a 𝟙𝟚` as 123, 12 and 12 respectively, so plain `/[0-9]/` is not
 * enough.
 *
 * No lookup table is shipped: `Nd` code points always come in aligned runs of
 * ten, and several runs may sit back to back (e.g. U+1D7CE..U+1D7FF holds five
 * consecutive styled-digit blocks).  Walking down to the start of the maximal
 * run and taking the offset modulo ten therefore recovers the digit value
 * without any per-block knowledge.
 */

const DECIMAL_DIGIT = /\p{Nd}/u;

const valueCache = new Map();

function isDecimalDigitCodePoint(codePoint) {
  if (codePoint < 0 || codePoint > 0x10ffff) return false;
  return DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
}

/**
 * Digit value of a single character, or -1 when it is not a decimal digit.
 * Mirrors the numeric half of CPython's `PyUnicode_ToDecimalDigit`.
 */
export function pyDecimalValue(char) {
  const codePoint = char.codePointAt(0);
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30; // fast path
  if (valueCache.has(codePoint)) return valueCache.get(codePoint);

  let value = -1;
  if (isDecimalDigitCodePoint(codePoint)) {
    let runStart = codePoint;
    while (runStart > 0 && isDecimalDigitCodePoint(runStart - 1)) runStart -= 1;
    value = (codePoint - runStart) % 10;
  }
  valueCache.set(codePoint, value);
  return value;
}

/** True when Python's regex `\d` (on a `str` pattern) would match `char`. */
export function isPyDigit(char) {
  return pyDecimalValue(char) >= 0;
}

