/**
 * Python's `repr()` for `str` and for single characters, plus the escape form
 * that `UnicodeEncodeError` uses (which is *not* `repr()` -- see below).
 */

// Categories excluded from `str.isprintable()`: Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs.
// U+0020 is the one Zs code point Python still calls printable.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** Equivalent of Python's `chr(codePoint).isprintable()`. */
export function isPyPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

/**
 * The `\xNN` / `\uXXXX` / `\UXXXXXXXX` escape, picked by magnitude exactly as
 * CPython does.
 */
export function unicodeEscape(codePoint) {
  if (codePoint < 0x100) return '\\x' + codePoint.toString(16).padStart(2, '0');
  if (codePoint < 0x10000) return '\\u' + codePoint.toString(16).padStart(4, '0');
  return '\\U' + codePoint.toString(16).padStart(8, '0');
}

function pickQuote(chars) {
  // Python prefers ' and only switches to " when the value contains ' but no ".
  return chars.includes("'") && !chars.includes('"') ? '"' : "'";
}

/** Equivalent of Python's `repr(text)` for a `str`. */
export function pyStrRepr(text) {
  const chars = Array.from(text);
  const quote = pickQuote(chars);
  let out = quote;
  for (const char of chars) {
    const codePoint = char.codePointAt(0);
    if (char === '\\') out += '\\\\';
    else if (char === quote) out += '\\' + quote;
    else if (codePoint === 0x09) out += '\\t';
    else if (codePoint === 0x0a) out += '\\n';
    else if (codePoint === 0x0d) out += '\\r';
    else if (isPyPrintable(codePoint)) out += char;
    else out += unicodeEscape(codePoint);
  }
  return out + quote;
}

/** Equivalent of Python's `repr(chr(codePoint))`. */
export function pyCharRepr(codePoint) {
  return pyStrRepr(String.fromCodePoint(codePoint));
}

/**
 * Equivalent of Python's `repr(bytes(...))` for an iterable of byte values.
 * Only `\\`, the quote, `\t`, `\n`, `\r` and non-ASCII-printable bytes are
 * escaped; everything in 0x20..0x7E is emitted literally.
 */
export function pyBytesRepr(byteValues) {
  const bytes = Array.from(byteValues);
  const quote = pickQuote(bytes.map((byte) => String.fromCharCode(byte)));
  const quoteByte = quote.charCodeAt(0);
  let out = 'b' + quote;
  for (const byte of bytes) {
    if (byte === 0x5c) out += '\\\\';
    else if (byte === quoteByte) out += '\\' + quote;
    else if (byte === 0x09) out += '\\t';
    else if (byte === 0x0a) out += '\\n';
    else if (byte === 0x0d) out += '\\r';
    else if (byte >= 0x20 && byte < 0x7f) out += String.fromCharCode(byte);
    else out += '\\x' + byte.toString(16).padStart(2, '0');
  }
  return out + quote;
}

