/**
 * The handful of Python exceptions this program can raise, carrying enough
 * information to reproduce CPython's traceback text.
 *
 * `pyFrames` holds the frames *inside* the library, outermost first; the entry
 * script prepends its own `<module>` frame before printing.
 */

import { unicodeEscape } from './repr.mjs';

export class PyException extends Error {
  constructor(typeName, pyMessage) {
    super(pyMessage ? `${typeName}: ${pyMessage}` : typeName);
    this.name = typeName;
    this.typeName = typeName;
    this.pyMessage = pyMessage;
    this.pyFrames = [];
  }

  /** The final `TypeName: message` line of a traceback. */
  get exceptionLine() {
    return this.pyMessage ? `${this.typeName}: ${this.pyMessage}` : this.typeName;
  }

  withFrames(frames) {
    this.pyFrames = frames;
    return this;
  }
}

export class PyValueError extends PyException {
  constructor(pyMessage) {
    super('ValueError', pyMessage);
  }
}

/**
 * `UnicodeEncodeError`'s message is built by CPython from a printf-style
 * template that always hex-escapes the offending character, even when the
 * character is printable -- hence `'你'` rather than the literal glyph.
 * A run of two or more unencodable characters switches to the plural
 * "characters in position start-end" form and names none of them.
 */
export class PyUnicodeEncodeError extends PyException {
  constructor(encoding, start, end, badCodePoint, reason) {
    const head = `'${encoding}' codec can't encode`;
    const message =
      end - start === 1
        ? `${head} character '${unicodeEscape(badCodePoint)}' in position ${start}: ${reason}`
        : `${head} characters in position ${start}-${end - 1}: ${reason}`;
    super('UnicodeEncodeError', message);
    this.encoding = encoding;
    this.start = start;
    this.end = end;
    this.reason = reason;
  }
}

