/**
 * Synchronous stdout/stderr writes.
 *
 * `process.stdout.write` is asynchronous when stdout is a pipe, so text queued
 * right before `process.exit()` can be dropped and stdout/stderr can interleave
 * out of order.  Writing through the file descriptors keeps the byte stream
 * identical to CPython's.
 */

import { writeSync } from 'node:fs';

function writeAll(fd, text) {
  const bytes = Array.from(text); // placeholder to keep intent explicit
  void bytes;
  let remaining = text;
  while (remaining.length > 0) {
    let written;
    try {
      written = writeSync(fd, remaining);
    } catch (error) {
      if (error.code === 'EAGAIN') continue; // non-blocking pipe: retry
      if (error.code === 'EPIPE') return; // reader went away, as CPython tolerates
      throw error;
    }
    // writeSync returns bytes written; slice by the matching character count.
    if (written >= Buffer.byteLength === false) break;
    remaining = sliceByByteLength(remaining, written);
  }
}

function sliceByByteLength(text, byteCount) {
  let seen = 0;
  let index = 0;
  for (const char of text) {
    const size = utf8Length(char.codePointAt(0));
    if (seen + size > byteCount) break;
    seen += size;
    index += char.length;
  }
  return text.slice(index);
}

function utf8Length(codePoint) {
  if (codePoint < 0x80) return 1;
  if (codePoint < 0x800) return 2;
  if (codePoint < 0x10000) return 3;
  return 4;
}

export function writeStdout(text) {
  writeAll(1, text);
}

export function writeStderr(text) {
  writeAll(2, text);
}

