/**
 * CPython traceback rendering, plus the PyInstaller epilogue the reference
 * build appends when a script dies of an unhandled exception:
 *
 *     Traceback (most recent call last):
 *       File "test14.py", line 12, in <module>
 *         decoded_int = base58.b58decode_int(args.c)  # ...
 *                       ^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *       File "base58/__init__.py", line 104, in b58decode_int
 *     ValueError: Invalid character '0'
 *     [PYI-1234:ERROR] Failed to execute script 'test14' due to unhandled exception!
 *
 * Frames from installed packages carry no `source`, because PyInstaller strips
 * the source of bundled dependencies -- only the entry script shows its code
 * line and caret underline.  The bracketed number is the process id.
 */

import { writeStderr } from './stdio.mjs';

const SOURCE_INDENT = 4;

/**
 * @param {{file: string, line: number, name: string, source?: string,
 *          caretStart?: number, caretLength?: number}} frame
 */
function formatFrame(frame) {
  const lines = [`  File "${frame.file}", line ${frame.line}, in ${frame.name}`];
  if (frame.source !== undefined) {
    lines.push(' '.repeat(SOURCE_INDENT) + frame.source);
    if (frame.caretLength) {
      lines.push(
        ' '.repeat(SOURCE_INDENT + frame.caretStart) + '^'.repeat(frame.caretLength),
      );
    }
  }
  return lines;
}

export function formatTraceback(exception, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) lines.push(...formatFrame(frame));
  lines.push(exception.exceptionLine);
  return lines.join('\n') + '\n';
}

/**
 * Print the traceback for an uncaught Python exception and exit 1, the way the
 * frozen executable does.
 *
 * @param {import('./exceptions.mjs').PyException} exception
 * @param {Array<object>} callerFrames frames above the library, outermost first
 * @param {string} scriptName name used in the PyInstaller epilogue
 */
export function abortWithTraceback(exception, callerFrames, scriptName) {
  const frames = [...callerFrames, ...exception.pyFrames];
  writeStderr(formatTraceback(exception, frames));
  writeStderr(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' ` +
      'due to unhandled exception!\n',
  );
  process.exit(1);
}

