/**
 * Python's `int(str)` conversion, returning a `BigInt` so that arbitrarily
 * large values keep full precision (the reference build happily encodes
 * 99999999999999999999999999).
 *
 * Accepted, as confirmed against the reference build:
 *   - surrounding Python whitespace, including U+00A0
 *   - a single leading `+` or `-`
 *   - any Unicode decimal digits (`١٢٣`, `１２`, `𝟙𝟚`)
 *   - single `_` separators *between* digits (`1_0`), but not `_10`, `10_`
 *     or `1__0`
 */

import { pyStrip } from './whitespace.mjs';
import { pyDecimalValue } from './unicode-digits.mjs';

/**
 * @returns {bigint|null} the parsed value, or null when Python's `int()` would
 *   raise `ValueError`.
 */
export function pyIntFromString(text) {
  const chars = Array.from(pyStrip(text));
  let index = 0;

  let negative = false;
  if (chars[index] === '+' || chars[index] === '-') {
    negative = chars[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < chars.length; index += 1) {
    const char = chars[index];
    if (char === '_') {
      if (!previousWasDigit) return null; // leading or doubled underscore
      previousWasDigit = false;
      continue;
    }
    const value = pyDecimalValue(char);
    if (value < 0) return null;
    digits += String(value);
    previousWasDigit = true;
  }
  if (!previousWasDigit) return null; // empty, sign-only, or trailing underscore

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/** Python's `divmod(a, b)`: the quotient floors, so the remainder takes b's sign. */
export function pyDivmod(a, b) {
  const remainder = ((a % b) + b) % b;
  return [(a - remainder) / b, remainder];
}

