/**
 * Enough of Python's `argparse.ArgumentParser` to match the reference build's
 * command line byte for byte: `--a` (int, required), `--b` (int, required),
 * `--c` (str, required), plus the implicit `-h/--help`.
 *
 * Behaviours pinned against the reference build:
 *   - `--a 1` and `--a=1` are equivalent; a repeated option keeps the last value
 *   - `--c -1` / `--c -1.5` are accepted as values (no option here looks like a
 *     negative number), but `--c -z` reports "expected one argument"
 *   - `-h` anywhere prints help and exits 0, before any required-argument check
 *   - missing required options are reported *before* unrecognized arguments
 *   - `--` and everything after it end up in the unrecognized list
 *   - type errors are reported as `argument --a: invalid int value: '12.5'`
 *   - every error prints the usage line, then `prog: error: ...`, and exits 2
 */

import { pyIntFromString } from './int.mjs';
import { pyStrRepr } from './repr.mjs';
import { isPyDigit } from './unicode-digits.mjs';
import { writeStderr, writeStdout } from './stdio.mjs';

const HELP_INDENT = 2;
const HELP_GAP = 2;

/** Python's `argparse` type converters, keyed by the name used in error text. */
export const TYPES = {
  int: { name: 'int', convert: pyIntFromString },
  str: { name: 'str', convert: (raw) => raw },
};

/**
 * argparse's `_negative_number_matcher`, i.e. `^-\d+$|^-\d*\.\d+$`.  The
 * pattern is compiled without `re.ASCII`, so `\d` spans all Unicode decimal
 * digits.
 */
