/**
 * `base58.scrub_input`: coerce a `str` argument to `bytes` via the ASCII codec.
 *
 * This is the first thing `b58decode_int` does, so a non-ASCII `--c` fails here
 * with `UnicodeEncodeError` and never reaches the alphabet lookup -- even when
 * the offending character sits after otherwise valid ones (`--c 'ab<emoji>'`)
 * or after an invalid ASCII one (`--c '~<han>'`).
 */

import { PyBytes } from '../py/bytes.mjs';
import { PyUnicodeEncodeError } from '../py/exceptions.mjs';

const SCRUB_INPUT_FRAME = { file: 'base58/__init__.py', line: 30, name: 'scrub_input' };

/** Frames a caller should append when `scrubInput` raises. */
export const SCRUB_INPUT_FRAMES = [SCRUB_INPUT_FRAME];

/**
 * Python's `text.encode('ascii')`.
 *
 * CPython reports the whole maximal run of unencodable characters starting at
 * the first failure, with positions counted in code points (so an astral
 * character counts as one).
 */
export function asciiEncode(text) {
  const chars = Array.from(text);
  const byteValues = [];
  for (let position = 0; position < chars.length; position += 1) {
    const codePoint = chars[position].codePointAt(0);
    if (codePoint < 0x80) {
      byteValues.push(codePoint);
      continue;
    }
    let end = position + 1;
    while (end < chars.length && chars[end].codePointAt(0) >= 0x80) end += 1;
    throw new PyUnicodeEncodeError(
      'ascii',
      position,
      end,
      codePoint,
      'ordinal not in range(128)',
    );
  }
  return new PyBytes(byteValues);
}

/**
 * `base58.scrub_input(v)`.  A `PyBytes` argument passes through unchanged; a JS
 * string is ASCII-encoded.
 */
export function scrubInput(value) {
  if (value instanceof PyBytes) return value;
  return asciiEncode(value);
}

