/**
 * `base58.b58encode_int` and `base58.b58decode_int`.
 *
 * Both are the integer-only halves of the library: they carry no leading-zero
 * padding logic, so they are pure base conversions over the alphabet.
 */

import { PyBytes } from '../py/bytes.mjs';
import { PyValueError } from '../py/exceptions.mjs';
import { pyDivmod } from '../py/int.mjs';
import { pyCharRepr } from '../py/repr.mjs';
import { pyRstrip } from '../py/whitespace.mjs';
import { BITCOIN_ALPHABET } from './alphabet.mjs';
import { SCRUB_INPUT_FRAMES, scrubInput } from './scrub-input.mjs';

const DECODE_INT_SCRUB_FRAME = {
  file: 'base58/__init__.py',
  line: 94,
  name: 'b58decode_int',
};
const DECODE_INT_LOOKUP_FRAME = {
  file: 'base58/__init__.py',
  line: 104,
  name: 'b58decode_int',
};

/**
 * `b58encode_int(i, default_one=True, alphabet=BITCOIN_ALPHABET)`.
 *
 * Note the `default_one` short circuit: 0 encodes to the *first* alphabet
 * character rather than the empty string, which is why the reference build
 * prints `b'1'` for `--a 0`.
 *
 * The loop uses Python's flooring `divmod`, so a negative `i` never converges
 * -- `divmod(-1, 58)` is `(-1, 57)`.  The reference build hangs on `--a -1` for
 * exactly this reason and the behaviour is reproduced rather than papered over.
 *
 * @param {bigint} i
 * @returns {PyBytes}
 */
export function b58encodeInt(i, defaultOne = true, alphabet = BITCOIN_ALPHABET) {
  if (i === 0n && defaultOne) return alphabet.slice(0, 1);

  const base = BigInt(alphabet.length);
  let remainingValue = i;
  let encoded = new PyBytes();
  while (remainingValue !== 0n) {
    const [quotient, index] = pyDivmod(remainingValue, base);
    remainingValue = quotient;
    encoded = encoded.prefixedWith(alphabet.slice(Number(index), Number(index) + 1));
  }
  return encoded;
}

/**
 * `b58decode_int(v, alphabet=BITCOIN_ALPHABET)`.
 *
 * The Bitcoin alphabet gets an `rstrip()` first -- `--c 'z  '` decodes to 57
 * while `--c '  z'` raises on the leading space -- and an all-whitespace or
 * empty string decodes to 0.
 *
 * @param {string|PyBytes} v
 * @returns {bigint}
 */
export function b58decodeInt(v, alphabet = BITCOIN_ALPHABET) {
  let value = v;
  if (alphabet.equals(BITCOIN_ALPHABET) && typeof value === 'string') {
    value = pyRstrip(value);
  }

  let scrubbed;
  try {
    scrubbed = scrubInput(value);
  } catch (error) {
    throw error.withFrames([DECODE_INT_SCRUB_FRAME, ...SCRUB_INPUT_FRAMES]);
  }

  const base = BigInt(alphabet.length);
  let decimal = 0n;
  for (const byte of scrubbed) {
    const index = alphabet.indexOfByte(byte);
    if (index < 0) {
      throw new PyValueError(`Invalid character ${pyCharRepr(byte)}`).withFrames([
        DECODE_INT_LOOKUP_FRAME,
      ]);
    }
    decimal = decimal * base + BigInt(index);
  }
  return decimal;
}

