/**
 * Python's `print()` for the value kinds this program produces.
 *
 * `bytes` objects render through `repr()` (so `print(b58encode_int(255))` shows
 * `b'5Q'`, quotes and all) while an `int` renders as bare decimal digits.
 */

import { PyBytes } from './bytes.mjs';
import { writeStdout } from './stdio.mjs';

/** Python's `str(value)`. */
export function pyStr(value) {
  if (value instanceof PyBytes) return value.repr();
  if (typeof value === 'bigint') return value.toString(10);
  return String(value);
}

export function print(...values) {
  writeStdout(values.map(pyStr).join(' ') + '\n');
}

