 *     encoded_int2 = base58.b58encode_int(args.b)
 *     decoded_int  = base58.b58decode_int(args.c)
 *     print(encoded_int1); print(encoded_int2); print(decoded_int)
 *
 * Run as: node test14.mjs --a 10000 --b 262631383 --c 5Q
 */

import { basename } from 'node:path';
import { ArgumentParser, TYPES } from './lib/py/argparse.mjs';
import { PyException } from './lib/py/exceptions.mjs';
import { print } from './lib/py/print.mjs';
import { abortWithTraceback } from './lib/py/traceback.mjs';
import { b58decodeInt, b58encodeInt } from './lib/base58/index.mjs';

// argparse defaults `prog` to basename(sys.argv[0]).
const PROG = basename(process.argv[1] ?? 'test14.mjs');

// The traceback quotes the *source* file, which stays test14.py in the frozen
// build regardless of how the program is invoked.
const SOURCE_FILE = 'test14.py';
const SCRIPT_NAME = 'test14';
const DECODE_STATEMENT = 'decoded_int = base58.b58decode_int(args.c)  # 解码为整数';
const DECODE_EXPRESSION = 'base58.b58decode_int(args.c)';
const DECODE_FRAME = {
  file: SOURCE_FILE,
  line: 12,
  name: '<module>',
  source: DECODE_STATEMENT,
  caretStart: DECODE_STATEMENT.indexOf(DECODE_EXPRESSION),
  caretLength: DECODE_EXPRESSION.length,
};

function main(argv) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--a', { type: TYPES.int, required: true });
  parser.addArgument('--b', { type: TYPES.int, required: true });
  parser.addArgument('--c', { type: TYPES.str, required: true });
  const args = parser.parseArgs(argv);

  const encodedInt1 = b58encodeInt(args.a); // 编码第一个整数
  const encodedInt2 = b58encodeInt(args.b); // 编码第二个整数

  // All three prints happen after the decode, so a bad --c produces a traceback
  // and no stdout at all.
  let decodedInt;
  try {
    decodedInt = b58decodeInt(args.c); // 解码为整数
  } catch (error) {
    if (error instanceof PyException) {
      abortWithTraceback(error, [DECODE_FRAME], SCRIPT_NAME);
    }
    throw error;
  }

  print(encodedInt1);
  print(encodedInt2);
  print(decodedInt);
}

main(process.argv.slice(2));

