  ['--a', '1', '--b', '2', '--c', 'z¡'],
  ['--a', '1', '--b', '2', '--c', '~你'],
  // argparse surface
  ['-h'],
  ['--help'],
  ['--h'],
  ['--a', '1', '--b', '2', '--c', 'z', '-h'],
  [],
  ['--a', '1', '--b', '2'],
  ['--a', '1', '--b', '2', '--c'],
  ['--a', '1', '--b', '2', '--c', 'z', '--d', '4'],
  ['--a', '1', '--b', '2', '--d', '4'],
  ['--a', '1', '--b', '2', '--c', 'z', 'extra'],
  ['--a', '1', '--a', '3', '--b', '2', '--c', 'z'],
  ['--a=7', '--b=8', '--c=9'],
  ['--', '--a', '1', '--b', '2', '--c', 'z'],
  ['--a', '1', '--b', '2', '--c', '--', 'z'],
  ['--a', '1', '--b', '2', '--c', '-z'],
  ['--a', '1', '--b', '2', '--c', '-1'],
  ['--a', '1', '--b', '2', '--c', '-1.5'],
  ['--a', '1', '--b', '2', '--c', '-a b'],
  ['--a', '1', '--b', '2', '--c', 'z', '-'],
  ['--a', '1', '--b', '2', '--c', 'z', '--'],
  ['--a', '1', '--b', '2', '--c', 'z', '--', 'foo'],
  ['--a', '-1', '--b', '1', '--c=z'],
];

const maskPid = (text) => text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

// The reference build names itself from argv[0]; the port names itself from the
// script it was launched as. Normalise so only real differences show up.
const normalise = (text) =>
  maskPid(text).replaceAll('test14_executable', 'PROG').replaceAll('test14.mjs', 'PROG');

function run(command, args, argv) {
  const result = spawnSync(command, [...args, ...argv], {
    encoding: 'utf8',
    timeout: 20_000,
  });
  return {
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
    status: result.status,
  };
}

let failures = 0;
for (const argv of CASES) {
  const expected = run(REFERENCE, [], argv);
  const actual = run(PORT[0], PORT.slice(1), argv);

  const same =
    normalise(expected.stdout) === normalise(actual.stdout) &&
    normalise(expected.stderr) === normalise(actual.stderr) &&
    expected.status === actual.status;

  if (!same) {
    failures += 1;
    console.log('MISMATCH', JSON.stringify(argv));
    console.log('  expected status', expected.status, 'actual', actual.status);
    if (normalise(expected.stdout) !== normalise(actual.stdout)) {
      console.log('  stdout py :', JSON.stringify(normalise(expected.stdout)));
      console.log('  stdout js :', JSON.stringify(normalise(actual.stdout)));
    }
    if (normalise(expected.stderr) !== normalise(actual.stderr)) {
      console.log('  stderr py :', JSON.stringify(normalise(expected.stderr)));
      console.log('  stderr js :', JSON.stringify(normalise(actual.stderr)));
    }
  }
}

console.log(`\n${CASES.length - failures}/${CASES.length} cases match`);
process.exit(failures === 0 ? 0 : 1);
